#[derive(Debug)]
enum Cell {
    Int(i32),
    Float(f64),
    Text(String),
}

fn main() {
    let row = vec![Cell::Int(3), Cell::Text(String::from("blue")), Cell::Float(10.12)];
    for cell in &row {
        match cell {
            Cell::Int(n) => println!("integer {n}"),
            Cell::Float(f) => println!("float {f}"),
            Cell::Text(s) => println!("text {s:?}"),
        }
    }
}

